INSERT OR REPLACE INTO kb_sources(source_id,title,source_kind,scope,authority,status,location,captured_at,version_fingerprint,notes) VALUES
('S-2026-10-07-CL-REGION-CLEANUP-AUDIT','Central Lodge Region visual clutter, usage classification and full rollback snapshot','verification','Central Lodge 21 scenes','Foundry 14.367 read-only Region inventory and audited full Region document backup','active','docs/CL-REGION-CLEANUP-AUDIT-2026-10-07.md; work/foundry-playwright-harness/receipts/region-cleanup-2026-10-07/manifest-v001.json','2026-10-07','202 Regions, 115 behaviors; backup sha256 761b64d5aaf67c8893ca6526e9997a18830bbb7c8c469e83eaf2ba6245549fa6','Backup of every toObject Region (shapes, flags, IDs and embedded behaviors), 843225 bytes, 21 scenes/202 Regions/115 behaviors, independently verified SHA-256. 95 Regions have zero behaviors but all are named for planned future functions; 7 literal active references, 88 without literals, none proven abandoned. 201 regions restricted to editing layer, one B1 Waterwheel has visibility=4. No Region deletions or other gameplay writes. A full restore was not tested because no deletion was justified.');

INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-2026-10-07-CL-REGION-CLEANUP-ZERO-PROVEN-ORPHANS','campaign.central-lodge.maintenance',NULL,'95 zero-behavior Regions are reserved future anchors, no proven orphan','A full Foundry no-write 21-Scene Region roster found 202 Regions with 115 behaviors, including 95 with no RegionBehaviors: 42 transition anchors, 4 tunnel-mouth transitions, 28 light owners, 11 system regions, 3 puzzle Regions, 3 item Regions, 3 horror/scare runtime anchors and 1 ambience runtime anchor. Seven empty Regions had literal references across Lodge RegionBehavior source, world Macros and Scene flags including F1/F2 arrival and N3 branch. The remaining 88 have authored future roles in the campaign plan; no orphan can be proven from zero behaviors or absence of a literal reference. In Foundry, 201 of 202 Region visibility settings are LAYER and need not display when using Tokens controls. Verified immutable full Region snapshot and manifest retained, no deletion made.','campaign','static','locked','S-2026-10-07-CL-REGION-CLEANUP-AUDIT',NULL,'central lodge region cleanup unused pending backup reversible overlays');
INSERT INTO facts_fts(fact_id,title,statement,tags) SELECT fact_id,title,statement,tags FROM kb_facts WHERE fact_id='F-2026-10-07-CL-REGION-CLEANUP-ZERO-PROVEN-ORPHANS'
AND NOT EXISTS(SELECT 1 FROM facts_fts f WHERE f.fact_id=kb_facts.fact_id);

INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-458','Do not delete authored empty Central Lodge Regions solely to declutter editing overlay','Preserve all 95 zero-RegionBehavior Regions until a candidate is proven abandoned or user explicitly approves archiving planned future Regions. Retain full immutable backup; ensure any future deletes have per-ID reviewed manifest, tested exact-ID restore and independent final verify. Use Tokens layer rather than Regions editing layer to conceal editing overlays without affecting gameplay.','All 95 have named plans for travel, lighting, puzzles, item pickup, atmosphere or system states; 7 are already literal destinations/references. All 201 normal Regions are only visible on editing layer.','campaign','locked','Foreman','S-2026-10-07-CL-REGION-CLEANUP-AUDIT',NULL);
