INSERT OR REPLACE INTO kb_open_items(item_id,item_class,title,problem,next_action,evidence_needed,priority,status,owner,source_id) VALUES
('O-2026-10-07-CL-REGION-ARCHIVE-CHOICE','reconciliation','Select intentional archive versus keep reserved future Region anchors','GM wants less map Region clutter, but 95 zero-behavior Regions all carry future role metadata, seven referenced immediately, and currently all normal Regions are confined to editor visibility. Deleting planned Regions would disrupt future work even if a backup permits restoration.','Ask user whether they want aggressive reversible archival of 88 currently-unreferenced yet planned anchors, or visual cleanup only via token-layer control. If archiving approved, test original-ID restore on disposable test Scene before any production deletion.','User confirmation to archive intentional planned Regions, backed by candidate allowlist and tested restore drill; no assumptions from zero behavior count.','P1','blocked','Foreman','S-2026-10-07-CL-REGION-CLEANUP-AUDIT');
